/*
 * fmaster - frequency display for the Collins S-line (75S -> 32S) and the Collins R390
 *
 * Measurement principle
 * ---------------------
 *  - One PCNT (pulse counter) unit per input counts rising edges while a "gate" signal is high.
 *  - The gate is generated by LEDC channel 0 on GPIO13 (2 Hz, high for 7936/8192 of the period)
 *    and looped back through R16 into GPIO12, which is the PCNT level (enable) input of every unit.
 *  - On the falling edge of the gate (GPIO12 interrupt) all counters are read and cleared.
 *    The counters are frozen while the gate is low, so they all cover exactly the same window.
 *  - Channel 0 counts the 20 MHz OCXO reference. The ratio "nominal reference / measured reference"
 *    is a calibration factor that removes the error of the ESP32's own crystal (it times the gate).
 *
 * Board: Collins_Freq_Meter (KiCad project in ../PCB/Collins_Freq_Meter)
 *   GPIO14  REF_CNT   20 MHz ECOC-7050 OCXO (via R1)
 *   GPIO27  CH1       75S VFO / PTO injection (2.5-2.7 MHz)
 *   GPIO26  CH2       R390 IF1   (J9)
 *   GPIO25  CH3       R390 IF2   (J10)
 *   GPIO33  CH4       R390 VFO   (J11)
 *   GPIO32  CH5       75S HF crystal-oscillator injection (~6.6-33 MHz), direct or /2 (JP1)
 *   GPIO2   INT       self-test input, from GPIO15 through R17 + JP2 (JP2 open by default)
 *   GPIO13 -> GPIO12  measurement gate loop-back (R16)
 *   GPIO15            1 MHz self-test output (LEDC channel 1)
 *   GPIO16 / GPIO17   I2C SDA / SCL to the 20x4 LCD (PCF8574 backpack, via 2N7000 level shifter)
 *   GPIO18/19/21      mode selector positions 0/1/2 (active low, JP3 grounds position 0)
 *   GPIO4             PTT sense (Q3 2N7000 pulls it low on TX)
 */
#include <stdio.h>
#include <string.h>
#include <inttypes.h>
#include <math.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"
#include "freertos/semphr.h"
#include "driver/gpio.h"
#include "driver/ledc.h"
#include "driver/pulse_cnt.h"
#include "driver/i2c.h"
#include "esp_err.h"
#include "esp_log.h"
#include "i2c-lcd.h"

static const char *TAG = "fmaster";

/* ============================================================================================
 * Board / build options
 * ============================================================================================ */
#define ENABLE_LCD_DISPLAY              /* comment out to run without the LCD (serial log only) */

/* Nominal reference frequency. The OCXO is +/-50 ppb over temperature but +/-500 ppb at delivery,
 * so for best absolute accuracy put the value measured against a good standard here. */
#define FREQ_REF_OSCILLATOR_HZ  20000000.0

/* CH5 (HFO) prescaler: 1 = JP1 at DIRECT (1-2), 2 = JP1 at DIV2 (2-3, through U4A 74LVC74A). */
#define HFO_PRESCALE            1

/* PCNT glitch filter. The filter works in APB clock cycles (12.5 ns at 80 MHz); 30 ns gave 2 cycles
 * and rejected the 20 MHz reference (25 ns half period) and every HFO above ~16 MHz.
 * The comparators have hysteresis and deliver clean edges, so the filter is off by default.
 * Set to e.g. 13 (= 1 APB cycle) only if a channel picks up glitches. 0 = filter disabled. */
#define PCNT_GLITCH_FILTER_NS   0

/* PTT sense polarity on GPIO4. Q3 pulls GPIO4 low when PTT_IN carries the keying voltage (JP9 open),
 * so TX = low. With JP9 fitted (contact closure to GND = TX) the sense is inverted: set this to 1. */
#define PTT_TX_LEVEL            0

/* ============================================================================================
 * GPIOs
 * ============================================================================================ */
#define GPIO_LEDC_MEASURE_PULSE     13  /* gate output (LEDC ch0) - wired to GPIO_PCNT_ENABLE_INPUT */
#define GPIO_PCNT_ENABLE_INPUT      12  /* gate input: counters run while high; falling edge = read */
#define GPIO_FCNT_INPUT_REFERENCE   14
#define GPIO_FCNT_INPUT_CH1         27
#define GPIO_FCNT_INPUT_CH2         26
#define GPIO_FCNT_INPUT_CH3         25
#define GPIO_FCNT_INPUT_CH4         33
#define GPIO_FCNT_INPUT_CH5         32
#define GPIO_FCNT_INPUT_INTERNAL    2   /* self-test input (from GPIO_INTERNAL_REF_OSC_OUT via JP2) */
#define GPIO_INTERNAL_REF_OSC_OUT   15  /* 1 MHz self-test output (LEDC ch1) */
#define GPIO_PTT_MODE               4
#define GPIO_DISPLAY_SDA            16
#define GPIO_DISPLAY_SCL            17
#define GPIO_SELECTOR_POSITION_0    18  /* selector inputs: internal pull-up, selected position = GND */
#define GPIO_SELECTOR_POSITION_1    19
#define GPIO_SELECTOR_POSITION_2    21

/* ============================================================================================
 * Counter channels (index into the arrays below)
 * ============================================================================================ */
enum {
    CH_REF = 0,     /* 20 MHz OCXO */
    CH_1,           /* 75S VFO */
    CH_2,           /* R390 IF1 */
    CH_3,           /* R390 IF2 */
    CH_4,           /* R390 VFO */
    CH_5,           /* 75S HFO */
    CH_INT,         /* self-test */
    NUM_FCNT_CHANNELS
};
#define FREQ_75S_VFO    CH_1
#define FREQ_75S_IF     CH_5    /* "IF" = HF crystal-oscillator injection from the 75S */
#define FREQ_390_IF1    CH_2
#define FREQ_390_IF2    CH_3
#define FREQ_390_VFO    CH_4

static const int gpio_num_input_freq[NUM_FCNT_CHANNELS] = {
    [CH_REF] = GPIO_FCNT_INPUT_REFERENCE,
    [CH_1]   = GPIO_FCNT_INPUT_CH1,
    [CH_2]   = GPIO_FCNT_INPUT_CH2,
    [CH_3]   = GPIO_FCNT_INPUT_CH3,
    [CH_4]   = GPIO_FCNT_INPUT_CH4,
    [CH_5]   = GPIO_FCNT_INPUT_CH5,
    [CH_INT] = GPIO_FCNT_INPUT_INTERNAL,
};
/* multiplier applied to each channel's count (external prescalers) */
static const int channel_prescale[NUM_FCNT_CHANNELS] = {
    [CH_REF] = 1, [CH_1] = 1, [CH_2] = 1, [CH_3] = 1, [CH_4] = 1, [CH_5] = HFO_PRESCALE, [CH_INT] = 1,
};

/* ============================================================================================
 * Modes
 *   0: Collins 75S -> 32S   (VFO and HFO from the 75S)
 *   1: Collins R390          (IF1, IF2, VFO of the R390)
 *   2: R390 receive / 32S transmit: shows mode 1 on RX and mode 0 on TX, switched by PTT
 * ============================================================================================ */
static const char *mode_name[3] = {"75S->32S", "R390->32S", "Reserved"};
static volatile int mode_operation = -1;    /* selector position, -1 = none selected */
static volatile int display_mode = -2;      /* what the display shows (0, 1, -1 = none), follows PTT in
                                               mode 2; -2 = not drawn yet */
#define PTT_RX 1
#define PTT_TX 0

/* ============================================================================================
 * Gate timing (LEDC) and counters
 * ============================================================================================ */
#define LEDC_MEASURE_FREQUENCY          2                   /* gate period: 1 / 2 Hz = 0.5 s */
#define FULL_DUTY                       8192                /* 13-bit duty resolution */
#define DUTY_CYCLE_PCNT                 (FULL_DUTY - 128)   /* gate high 7936/8192 of the period */
#define LEDC_INTERNAL_REFERENCE_FREQ    1000000             /* 1 MHz self-test output */
/* gate length in seconds = DUTY_CYCLE_PCNT / FULL_DUTY / LEDC_MEASURE_FREQUENCY (~0.484 s) */

/* The PCNT hardware counter is 16 bit. With accum_count the driver extends it in software each time
 * it reaches the limit, so pcnt_unit_get_count() returns the full count of the gate period. */
#define FCNT_LIMIT  32000

static pcnt_unit_handle_t pcnt_units[NUM_FCNT_CHANNELS];
static volatile int32_t total_cnts[NUM_FCNT_CHANNELS];     /* raw counts of the last gate (ISR) */
static int32_t measured_freqs[NUM_FCNT_CHANNELS];          /* Hz, from the ESP32 time base */
static int32_t calibrated_freqs[NUM_FCNT_CHANNELS];        /* Hz, corrected by the OCXO */
static double calibration_factor = 1.0;
static QueueHandle_t fmaster_evt_queue = NULL;

/* optional moving average over the last num_moving_average readings */
#define MAX_MOVING_AVERAGE 16
static int show_moving_average = 0;
static int num_moving_average = 2;
static int32_t freq_average_buffer[NUM_FCNT_CHANNELS][MAX_MOVING_AVERAGE];
static int pt_freq_average[NUM_FCNT_CHANNELS];

/* S-line carrier offset: the 75S/32S carrier (BFO) crystals are 453.650 kHz (USB) and 456.350 kHz
 * (LSB), i.e. 455 kHz -/+ 1.35 kHz. The correct sign depends on the sideband switch, not the band;
 * the "< 8 MHz = LSB" rule below only matches the usual sideband per band. */
#define SLINE_BFO_OFFSET_HZ     1350
#define SLINE_LSB_BELOW_HZ      8000000
#define SLINE_IF_HZ             455000

/* ============================================================================================
 * GPIO setup
 * ============================================================================================ */
static void setup_gpio_input(int pinnum, bool pullup)
{
    gpio_reset_pin((gpio_num_t)pinnum);
    gpio_set_direction((gpio_num_t)pinnum, GPIO_MODE_INPUT);
    if (pullup) {
        gpio_set_pull_mode((gpio_num_t)pinnum, GPIO_PULLUP_ONLY);
    }
}

static void init_GPIOs(void)
{
    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        setup_gpio_input(gpio_num_input_freq[i], false);
    }
    setup_gpio_input(GPIO_SELECTOR_POSITION_0, true);
    setup_gpio_input(GPIO_SELECTOR_POSITION_1, true);
    setup_gpio_input(GPIO_SELECTOR_POSITION_2, true);
    setup_gpio_input(GPIO_PTT_MODE, true);      /* R46 on the board also pulls it up */
}

/* selector position 0..2, or -1 if no position is grounded */
static int read_selector_position(void)
{
    if (gpio_get_level(GPIO_SELECTOR_POSITION_0) == 0) return 0;
    if (gpio_get_level(GPIO_SELECTOR_POSITION_1) == 0) return 1;
    if (gpio_get_level(GPIO_SELECTOR_POSITION_2) == 0) return 2;
    return -1;
}

static int read_ptt_position(void)
{
    return (gpio_get_level(GPIO_PTT_MODE) == PTT_TX_LEVEL) ? PTT_TX : PTT_RX;
}

/* ============================================================================================
 * I2C and display
 * ============================================================================================ */
#define I2C_MASTER_NUM      0
#define I2C_MASTER_FREQ_HZ  400000

/* Both tasks write to the LCD; a whole update (cursor move + text) must not be interleaved. */
static SemaphoreHandle_t lcd_mutex;
#define LCD_LOCK()      xSemaphoreTake(lcd_mutex, portMAX_DELAY)
#define LCD_UNLOCK()    xSemaphoreGive(lcd_mutex)

static esp_err_t i2c_master_init(void)
{
    i2c_config_t conf = {
        .mode = I2C_MODE_MASTER,
        .sda_io_num = GPIO_DISPLAY_SDA,
        .scl_io_num = GPIO_DISPLAY_SCL,
        .sda_pullup_en = GPIO_PULLUP_ENABLE,    /* board has 4.7k pull-ups as well (R18, R20) */
        .scl_pullup_en = GPIO_PULLUP_ENABLE,
        .master.clk_speed = I2C_MASTER_FREQ_HZ,
    };
    ESP_ERROR_CHECK(i2c_param_config(I2C_MASTER_NUM, &conf));
    return i2c_driver_install(I2C_MASTER_NUM, conf.mode, 0, 0, 0);
}

static void init_display(void)
{
    lcd_mutex = xSemaphoreCreateMutex();
    ESP_ERROR_CHECK(i2c_master_init());
    lcd_init();
    lcd_clear();
}

/* fills all 20 x 4 positions - handy to check the LCD wiring (call it from app_main) */
static void __attribute__((unused)) test_display(void)
{
    lcd_put_cur(0, 0); lcd_send_string("A123456789012345678A");
    lcd_put_cur(1, 0); lcd_send_string("B123456789012345678B");
    lcd_put_cur(2, 0); lcd_send_string("C123456789012345678C");
    lcd_put_cur(3, 0); lcd_send_string("D123456789012345678D");
}

/* "dd,ddd,ddd" (10 characters), clamped to 99,999,999 Hz */
static void format_freq(char *buf, size_t len, int32_t hz)
{
    if (hz < 0) hz = 0;
    if (hz > 99999999) hz = 99999999;
    snprintf(buf, len, "%02" PRId32 ",%03" PRId32 ",%03" PRId32,
             hz / 1000000, (hz / 1000) % 1000, hz % 1000);
}

static void lcd_show_freq(int row, int32_t hz)
{
#ifdef ENABLE_LCD_DISPLAY
    char buf[16];
    format_freq(buf, sizeof(buf), hz);
    LCD_LOCK();
    lcd_put_cur(row, 8);
    lcd_send_string(buf);
    LCD_UNLOCK();
#endif
}

static void lcd_show_mode_header(const char *line0)
{
#ifdef ENABLE_LCD_DISPLAY
    LCD_LOCK();
    lcd_put_cur(0, 0); lcd_send_string((char *)line0);
    lcd_put_cur(1, 0); lcd_send_string("IF :                ");
    lcd_put_cur(2, 0); lcd_send_string("VFO:                ");
    lcd_put_cur(3, 0); lcd_send_string("fc :                ");
    LCD_UNLOCK();
#endif
}

/* ============================================================================================
 * LEDC: measurement gate (ch0) and 1 MHz self-test signal (ch1)
 * ============================================================================================ */
static void config_ledc_init(void)
{
    ledc_timer_config_t gate_timer = {
        .speed_mode      = LEDC_LOW_SPEED_MODE,
        .duty_resolution = LEDC_TIMER_13_BIT,
        .timer_num       = LEDC_TIMER_0,
        .freq_hz         = LEDC_MEASURE_FREQUENCY,
        .clk_cfg         = LEDC_AUTO_CLK,
    };
    ESP_ERROR_CHECK(ledc_timer_config(&gate_timer));
    ledc_channel_config_t gate_channel = {
        .speed_mode = LEDC_LOW_SPEED_MODE,
        .channel    = LEDC_CHANNEL_0,
        .timer_sel  = LEDC_TIMER_0,
        .intr_type  = LEDC_INTR_DISABLE,
        .gpio_num   = GPIO_LEDC_MEASURE_PULSE,
        .duty       = DUTY_CYCLE_PCNT,
        .hpoint     = 0,
    };
    ESP_ERROR_CHECK(ledc_channel_config(&gate_channel));

    ledc_timer_config_t test_timer = {
        .speed_mode      = LEDC_LOW_SPEED_MODE,
        .duty_resolution = LEDC_TIMER_2_BIT,
        .timer_num       = LEDC_TIMER_1,
        .freq_hz         = LEDC_INTERNAL_REFERENCE_FREQ,
        .clk_cfg         = LEDC_AUTO_CLK,
    };
    ESP_ERROR_CHECK(ledc_timer_config(&test_timer));
    ledc_channel_config_t test_channel = {
        .speed_mode = LEDC_LOW_SPEED_MODE,
        .channel    = LEDC_CHANNEL_1,
        .timer_sel  = LEDC_TIMER_1,
        .intr_type  = LEDC_INTR_DISABLE,
        .gpio_num   = GPIO_INTERNAL_REF_OSC_OUT,
        .duty       = 2,                /* 2 of 4 = 50 % */
        .hpoint     = 1,
    };
    ESP_ERROR_CHECK(ledc_channel_config(&test_channel));
}

/* ============================================================================================
 * Gate falling edge: read and clear all counters (they are frozen while the gate is low).
 * Not placed in IRAM (the PCNT calls aren't either: CONFIG_PCNT_CTRL_FUNC_IN_IRAM is off), which is
 * fine because the application never writes flash at run time.
 * ============================================================================================ */
static void gate_isr_handler(void *arg)
{
    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        int count = 0;
        pcnt_unit_get_count(pcnt_units[i], &count);
        pcnt_unit_clear_count(pcnt_units[i]);
        total_cnts[i] = count;
    }
    uint32_t gpio_num = (uint32_t)arg;
    BaseType_t woken = pdFALSE;
    xQueueSendFromISR(fmaster_evt_queue, &gpio_num, &woken);
    if (woken) {
        portYIELD_FROM_ISR();
    }
}

/* ============================================================================================
 * PCNT: one unit per channel, counting rising edges while the gate (level input) is high
 * ============================================================================================ */
static void init_freq_pcnt(void)
{
    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        pcnt_unit_config_t unit_config = {
            .high_limit = FCNT_LIMIT,
            .low_limit = -FCNT_LIMIT,
            .flags.accum_count = 1,         /* extend the 16-bit counter in software */
        };
        ESP_ERROR_CHECK(pcnt_new_unit(&unit_config, &pcnt_units[i]));

#if PCNT_GLITCH_FILTER_NS > 0
        pcnt_glitch_filter_config_t filter_config = { .max_glitch_ns = PCNT_GLITCH_FILTER_NS };
        ESP_ERROR_CHECK(pcnt_unit_set_glitch_filter(pcnt_units[i], &filter_config));
#endif

        pcnt_chan_config_t chan_config = {
            .edge_gpio_num = gpio_num_input_freq[i],
            .level_gpio_num = GPIO_PCNT_ENABLE_INPUT,
        };
        pcnt_channel_handle_t chan;
        ESP_ERROR_CHECK(pcnt_new_channel(pcnt_units[i], &chan_config, &chan));
        /* count on the rising edge, ignore the falling edge */
        ESP_ERROR_CHECK(pcnt_channel_set_edge_action(chan, PCNT_CHANNEL_EDGE_ACTION_INCREASE,
                                                     PCNT_CHANNEL_EDGE_ACTION_HOLD));
        /* gate high: count normally; gate low: hold */
        ESP_ERROR_CHECK(pcnt_channel_set_level_action(chan, PCNT_CHANNEL_LEVEL_ACTION_KEEP,
                                                      PCNT_CHANNEL_LEVEL_ACTION_HOLD));
        /* accum_count needs the limits as watch points */
        ESP_ERROR_CHECK(pcnt_unit_add_watch_point(pcnt_units[i], FCNT_LIMIT));
        ESP_ERROR_CHECK(pcnt_unit_add_watch_point(pcnt_units[i], -FCNT_LIMIT));

        ESP_ERROR_CHECK(pcnt_unit_enable(pcnt_units[i]));
        ESP_ERROR_CHECK(pcnt_unit_clear_count(pcnt_units[i]));
        ESP_ERROR_CHECK(pcnt_unit_start(pcnt_units[i]));
    }
}

/* ============================================================================================
 * Main measurement task: convert counts to Hz, calibrate, display
 * ============================================================================================ */
static void update_frequencies(void)
{
    const double gate_s = (double)DUTY_CYCLE_PCNT / FULL_DUTY / LEDC_MEASURE_FREQUENCY;

    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        measured_freqs[i] = (int32_t)lround((double)total_cnts[i] * channel_prescale[i] / gate_s);
    }

    /* Calibrate against the OCXO. Skip it while the reference is missing or implausible
     * (OCXO unpowered on USB-only supply, or still warming up), and keep the last factor. */
    static bool ref_ok = true;
    double ref = (double)measured_freqs[CH_REF];
    bool ok = ref > FREQ_REF_OSCILLATOR_HZ * 0.999 && ref < FREQ_REF_OSCILLATOR_HZ * 1.001;
    if (ok) {
        calibration_factor = FREQ_REF_OSCILLATOR_HZ / ref;
    }
    if (ok != ref_ok) {             /* log state changes only, not every gate period */
        ref_ok = ok;
        if (ok) {
            ESP_LOGI(TAG, "reference OK (%.0f Hz) - calibration active", ref);
        } else {
            ESP_LOGW(TAG, "reference %.0f Hz out of range - keeping the last calibration factor", ref);
        }
    }

    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        calibrated_freqs[i] = (int32_t)lround(measured_freqs[i] * calibration_factor);
    }

    if (show_moving_average) {
        for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
            freq_average_buffer[i][pt_freq_average[i]] = calibrated_freqs[i];
            pt_freq_average[i] = (pt_freq_average[i] + 1) % num_moving_average;
            int64_t sum = 0;
            for (int k = 0; k < num_moving_average; k++) {
                sum += freq_average_buffer[i][k];
            }
            calibrated_freqs[i] = (int32_t)(sum / num_moving_average);
        }
    }

    for (int i = 0; i < NUM_FCNT_CHANNELS; i++) {
        printf("f[%d]=%" PRId32 " cal=%" PRId32 "  ", i, measured_freqs[i], calibrated_freqs[i]);
    }
    printf("\n");
}

static void main_task_loop(void *arg)
{
    uint32_t io_num;
    for (;;) {
        if (!xQueueReceive(fmaster_evt_queue, &io_num, portMAX_DELAY)) {
            continue;
        }
        update_frequencies();

        if (display_mode == 0) {
            /* Collins S-line: carrier = HFO - VFO - 455 kHz, corrected for the BFO offset */
            int32_t if_75s = calibrated_freqs[FREQ_75S_IF];
            int32_t vfo_75s = calibrated_freqs[FREQ_75S_VFO];
            int32_t fc_75s = if_75s - vfo_75s - SLINE_IF_HZ;
            fc_75s += (fc_75s < SLINE_LSB_BELOW_HZ) ? SLINE_BFO_OFFSET_HZ : -SLINE_BFO_OFFSET_HZ;

            lcd_show_freq(1, if_75s);
            lcd_show_freq(2, vfo_75s);
            lcd_show_freq(3, fc_75s);
        } else if (display_mode == 1) {
            /* Collins R390. NOTE: formula carried over from the prototype - verify it against
             * the R390 frequency scheme. IF2 is measured but has no line of its own on the LCD. */
            int32_t if1_390 = calibrated_freqs[FREQ_390_IF1];
            int32_t if2_390 = calibrated_freqs[FREQ_390_IF2];
            int32_t vfo_390 = calibrated_freqs[FREQ_390_VFO];
            int32_t fc_390 = if1_390 - if2_390 - vfo_390 - SLINE_IF_HZ;

            lcd_show_freq(1, if1_390);
            lcd_show_freq(2, vfo_390);
            lcd_show_freq(3, fc_390);
        }
    }
}

/* ============================================================================================
 * Mode handling (selector + PTT), polled every 200 ms
 * ============================================================================================ */
static void show_mode(int mode)
{
    if (mode == display_mode) {
        return;
    }
    display_mode = mode;
    if (mode == 0) {
        lcd_show_mode_header("W1TOY,  Collins S   ");
    } else if (mode == 1) {
        lcd_show_mode_header("W1TOY,  Collins R390");
    } else {
        lcd_show_mode_header("W1TOY, select mode  ");
    }
    ESP_LOGI(TAG, "display mode %d", mode);
}

static void mode_switch_loop(void *arg)
{
    int previous_selector = -2;
    for (;;) {
        int selector = read_selector_position();
        if (selector != previous_selector) {
            previous_selector = selector;
            mode_operation = selector;
            ESP_LOGI(TAG, "selector position %d (%s)", selector, selector >= 0 ? mode_name[selector] : "none");
        }
        if (mode_operation == 2) {
            /* R390 receives, 32S transmits on the 75S clocks */
            show_mode(read_ptt_position() == PTT_RX ? 1 : 0);
        } else {
            show_mode(mode_operation);      /* 0, 1 or -1 (nothing selected) */
        }
        vTaskDelay(pdMS_TO_TICKS(200));
    }
}

/* ============================================================================================
 * Entry point
 * ============================================================================================ */
void app_main(void)
{
    init_GPIOs();
#ifdef ENABLE_LCD_DISPLAY
    init_display();
#endif
    config_ledc_init();
    init_freq_pcnt();

    fmaster_evt_queue = xQueueCreate(10, sizeof(uint32_t));

    /* read the counters on the falling edge of the gate */
    gpio_set_intr_type(GPIO_PCNT_ENABLE_INPUT, GPIO_INTR_NEGEDGE);
    gpio_install_isr_service(0);
    gpio_isr_handler_add(GPIO_PCNT_ENABLE_INPUT, gate_isr_handler, (void *)GPIO_PCNT_ENABLE_INPUT);

    xTaskCreate(main_task_loop, "main_task_loop", 4096, NULL, 10, NULL);
    xTaskCreate(mode_switch_loop, "mode_switch_loop", 4096, NULL, 10, NULL);
}
